UPDATE stories SET html_en = '<h3>🇲🇾 Malaysia — related companies of RM1m+ groups now in scope</h3><p>Here''s the one most likely to catch a business off guard: even if your own revenue is well under Malaysia''s thresholds, if you''re a subsidiary or related company of a group with RM1 million or more in turnover, you''re in scope from 1 July regardless of your own individual size. Group structure, not standalone revenue, is what determines whether you''re caught here.</p>' WHERE id = '2026-06-01-malaysia-related-company-rule-preview';
UPDATE story_translations SET html = '<h3>🇲🇾 Malaysia — related companies of RM1m+ groups now in scope</h3><p>Here''s the one most likely to catch a business off guard: even if your own revenue is well under Malaysia''s thresholds, if you''re a subsidiary or related company of a group with RM1 million or more in turnover, you''re in scope from 1 July regardless of your own individual size. Group structure, not standalone revenue, is what determines whether you''re caught here.</p>' WHERE story_id = '2026-06-01-malaysia-related-company-rule-preview' AND lang = 'en';
UPDATE stories SET html_en = '<h3>🇦🇪 UAE — voluntary e-invoicing pilot opens</h3><p>Ahead of the mandatory phases starting January 2027, the UAE opens voluntary participation this date — letting businesses test Accredited Service Provider connectivity and the PINT AE format risk-free before penalties apply. Given the ASP appointment deadline for large businesses lands in October, using this pilot window well ahead of that is genuinely the sensible order to do things in.</p><p><strong>What this means for your team:</strong> if any of these four apply to you, this is the month to actually finish testing, not start it. 1 July arrives fast, and none of these four give much grace period once the date passes.</p>' WHERE id = '2026-06-01-uae-voluntary-pilot-preview';
